// ─── Lookup Helpers ─────────────────────────────────────────────────

const BY_SLUG = new Map(CREATORS_DATASET.map((c) => [c.slug, c]));
const BY_ID = new Map(CREATORS_DATASET.map((c) => [c.id, c]));

export function getCreatorEntryBySlug(slug: string): CreatorEntry | undefined {
  return BY_SLUG.get(slug);
}

export function getCreatorEntryById(id: string): CreatorEntry | undefined {
  return BY_ID.get(id);
}

export function listAllCreatorEntries(): readonly CreatorEntry[] {
  return CREATORS_DATASET;
}

export function listCreatorsByCategory(category: string): CreatorEntry[] {
  const lower = category.toLowerCase();
  return CREATORS_DATASET.filter((c) => c.category.toLowerCase() === lower);
}

export function listCreatorsByCountry(countryCode: string): CreatorEntry[] {
  return CREATORS_DATASET.filter((c) => c.countryCode === countryCode);
}

export function listCreatorsByNiche(niche: string): CreatorEntry[] {
  return CREATORS_DATASET.filter((c) => c.niche === niche);
}

export function listUnverifiedCreators(): CreatorEntry[] {
  return CREATORS_DATASET.filter((c) => !c.verified);
}
